import ApplicationServices
import Foundation

func attribute<T>(_ node: AXUIElement, _ name: String) -> T? {
    var value: CFTypeRef?
    guard AXUIElementCopyAttributeValue(node, name as CFString, &value) == .success else { return nil }
    return value as? T
}

let labels = Set(["首页", "会话", "对话", "设置", "项目", "搜索结果", "新建对话", "来源", "迁移…",
                  "恢复会话", "消息", "全 部", "清除搜索", "本地状态", "工作目录", "取消", "创建对话",
                  "搜索标题与消息", "开始一段对话", "选择一个历史会话", "没有匹配的对话"])
let expectedDirectory = ProcessInfo.processInfo.environment["RAGDOLL_SMOKE_PROJECT"]
var verifiedDirectory = false
var cancelButton: AXUIElement?

func describe(_ node: AXUIElement<truncated omitted_approx_tokens="4" /> let role: String = attribute(node, "AXRole") ?? "unknown"
    let values = ["AXTitle", "AXDescription", "AXValue", "AXPlaceholderValue"].compactMap { attribute(node, $0) as String? }
    let known = values.filter { labels.contains($0) }
    let other = values.isEmpty || !known.isEmpty ? "" : " [内容已省略]"
    print(String(repeating: " ", count: depth) + role + " " + known.joined(separator: "/") + other)
    if let expectedDirectory, role == "AXTextField", (attribute(node, "AXValue") as String?) == expectedDirectory {
        verifiedDirectory = true
    }
    if insideSheet && role == "AXTextField" {
        let value: String = attribute(node, "AXValue") ?? ""
        let alternative = ProcessInfo.processInfo.environment["RAGDOLL_SMOKE_OTHER_PROJECT"]
        print("FIELD length=\(value.count) isHome=\(value == FileManager.default.homeDirectoryForCurrentUser.path) isOtherProject=\(value == alternative)")
    }
    if role == "AXButton" && known.contains("取消") { cancelButton = node }
    let children: [AXUIElement] = attribute(node, "AXChildren") ?? []
    for child in children where depth < 10 { describe(child, depth + 1, insideSheet: insideSheet || role == "AXSheet") }
}

func descendants(_ node: AXUIElement, depth: Int = 0) -> [AXUIElement] {
    guard depth < 13 else { return [] }
    let children: [AXUIElement] = attribute(node, "AXChildren") ?? []
    return [node] + children.flatMap { descendants($0, depth: depth + 1) }
}

func matches(_ node: AXUIElement, role: String, text: String) -> Bool {
    let actual: String? = attribute(node, "AXRole")
    return actual == role && ["AXTitle", "AXDescription", "AXValue", "AXPlaceholderValue"].contains {
        (attribute(node, $0) as String?) == text
    }
}

func expect(_ condition: @autoclosure () -> Bool, _ message: String) {
    guard condition() else { print("FAIL " + message); exit(1) }
"}

